/* 200 exercises for grade 6: seven topics and four difficulty levels. */
(()=>{
 const add=(topic,level,i,question,answer,steps,hint)=>tasks.push({id:`grade6-practice-${topic}-${level}-${i}`,domain:'math',grade:6,subject:'math',topic,topicName:curriculum[6][topic][0],level,title:['Вычисление','Задача в несколько шагов','Задача на рассуждение','Олимпиадная задача'][level]+' · '+(i+1),question,answer,hints:[hint,'Проверь результат подстановкой или обратным действием.'],steps,review:{plan:hint,verify:steps[steps.length-1],trap:'Внимательно проверь, какую величину требуется найти.'},challenge:level>=2,goal:'Разобраться в решении и проверить ответ'});
 for(let topic=0;topic<7;topic++)for(let level=0;level<4;level++)for(let i=0;i<7+(topic===level?1:0);i++){
  const n=i+2;let q,a,s,h;
  if(topic===0){
   if(level===0){q=`Найди 10% от ${n*100}.`;a=n*10;s=[`10% — это одна десятая числа.`,`${n*100} : 10 = ${a}.`];h='Переведи процент в дробь.';}
   if(level===1){q=`После скидки 20% цена стала ${n*80} рублей. Какой была цена до скидки?`;a=n*100;s=[`После скидки осталось 80% цены.`,`${n*80} : 0,8 = ${a} рублей.`];h='Найди, какая доля цены осталась.';}
   if(level===2){q=`Цену ${n*100} рублей повысили на 20%, а затем снизили на 25%. Сколько рублей стала стоить вещь?`;a=n*90;s=[`После повышения цена ${n*100}·1,2 = ${n*120}.`,`После снижения ${n*120}·0,75 = ${a} рублей.`];h='Применяй каждый процент к новой цене.';}
   if(level===3){q=`Цену сначала повысили на 20%, затем снизили на 25%. Итоговая цена ${n*90} рублей. Найди первоначальную цену.`;a=n*100;s=[`Общий множитель равен 1,2·0,75 = 0,9.`,`Первоначальная цена ${n*90} : 0,9 = ${a} рублей.`];h='Найди общий множитель двух изменений.';}
  }
  if(topic===1){
   if(level===0){q=`Вычисли: −${n+5} + ${n}.`;a=-5;s=[`Из ${n+5} отрицательных единиц компенсируем ${n}.`,`Остаётся ${a}.`];h='Сравни модули слагаемых.';}
   if(level===1){q=`Вычисли: 1/2 + ${n}/10. Ответ запиши числом.`;a=(5+n)/10;s=[`1/2 = 5/10.`,`(5 + ${n})/10 = ${a}.`];h='Приведи дроби к знаменателю 10.';}
   if(level===2){q=`Найди значение выражения −2·(${n} − 3) + 3·${n}.`;a=n+6;s=[`Раскроем скобки: −2·${n} + 6 + 3·${n}.`,`После приведения получаем ${n} + 6 = ${a}.`];h='Раскрой скобки, учитывая знак минус.';}
   if(level===3){q=`Реши уравнение (x − ${n})/3 = (x + 2)/5. Найди x.`;a=(5*n+6)/2;s=[`После умножения на 15: 5(x − ${n}) = 3(x + 2).`,`2x = ${5*n+6}, следовательно x = ${a}.`];h='Умножь обе части на 15.';}
  }
  if(topic===2){
   if(level===0){q=`Есть ${n+2} футболок и 3 пары брюк. Сколько разных комплектов из футболки и брюк можно составить?`;a=(n+2)*3;s=[`Для каждой футболки доступны 3 пары брюк.`,`${n+2}·3 = ${a} комплектов.`];h='Примени правило произведения.';}
   if(level===1){q=`В группе ${n+3} человек. Каждый пожал руку каждому один раз. Сколько рукопожатий было?`;a=(n+3)*(n+2)/2;s=[`У каждого из ${n+3} человек есть ${n+2} партнёра.`,`Каждое рукопожатие учтено дважды: ${n+3}·${n+2}/2 = ${a}.`];h='Посчитай пары и устрани двойной счёт.';}
   if(level===2){let m=n+2;q=`Есть ${m} различных букв. Сколько трёхбуквенных кодов можно составить без повторения букв?`;a=m*(m-1)*(m-2);s=[`Первую букву можно выбрать ${m} способами, вторую — ${m-1}, третью — ${m-2}.`,`${m}·${m-1}·${m-2} = ${a}.`];h='Для каждой следующей позиции остаётся меньше вариантов.';}
   if(level===3){let m=n+3;q=`Из ${m} разных книг выбирают 3 для выставки. Порядок не важен. Сколько существует выборов?`;a=m*(m-1)*(m-2)/6;s=[`Упорядоченных троек ${m}·${m-1}·${m-2}.`,`Каждый набор учтён 3! = 6 раз, поэтому ответ ${a}.`];h='Сначала учти порядок, затем убери повторения.';}
  }
  if(topic===3){
   if(level===0){q=`За 1 кг яблок платят ${n*10} рублей. Сколько рублей стоят 3 кг по той же цене?`;a=n*30;s=[`Стоимость прямо пропорциональна массе.`,`${n*10}·3 = ${a} рублей.`];h='Умножь цену килограмма на массу.';}
   if(level===1){q=`5 кг крупы стоят ${n*50} рублей. Сколько рублей стоят 8 кг по той же цене?`;a=n*80;s=[`Цена 1 кг: ${n*50} : 5 = ${n*10} рублей.`,`Цена 8 кг: ${n*10}·8 = ${a} рублей.`];h='Сначала найди стоимость 1 кг.';}
   if(level===2){q=`За 4 часа станок делает ${n*20} деталей с постоянной скоростью. Сколько деталей он сделает за 7 часов?`;a=n*35;s=[`За час станок делает ${n*20} : 4 = ${n*5} деталей.`,`За 7 часов: ${n*5}·7 = ${a} деталей.`];h='Найди производительность за час.';}
   if(level===3){q=`Две трубы вместе наполняют бассейн за ${n*2} часов; первая одна — за ${n*3} часов. За сколько часов наполнит бассейн одна вторая труба?`;a=n*6;s=[`За час обе трубы наполняют 1/${n*2} бассейна, первая — 1/${n*3}.`,`Вторая наполняет 1/${n*2} − 1/${n*3} = 1/${n*6} бассейна в час. Её время: ${a} ч.`];h='Вычитай скорости наполнения, а не времена.';}
  }
  if(topic===4){
   if(level===0){q=`Точки A(${n}; 0) и B(${n+5}; 0) лежат на оси Ox. Найди длину AB.`;a=5;s=[`Обе точки на одной горизонтальной оси.`,`${n+5} − ${n} = ${a}.`];h='Вычти координаты точек на оси.';}
   if(level===1){q=`Найди абсциссу середины отрезка с концами A(${n}; 2) и B(${n+8}; 2).`;a=n+4;s=[`Абсцисса середины — среднее абсцисс концов.`,`(${n} + ${n+8})/2 = ${a}.`];h='Сложи абсциссы и раздели на два.';}
   if(level===2){q=`Вершины прямоугольника имеют координаты (0;0), (${n};0), (${n};4), (0;4). Найди его площадь.`;a=n*4;s=[`Длины сторон равны ${n} и 4.`,`Площадь равна ${n}·4 = ${a}.`];h='Найди длины горизонтальной и вертикальной сторон.';}
   if(level===3){q=`Точки A(−${n};0), B(${n};0), C(0;${n+1}) образуют треугольник. Найди его площадь.`;a=n*(n+1);s=[`Основание AB равно ${2*n}, высота из C равна ${n+1}.`,`S = ${2*n}·${n+1}/2 = ${a}.`];h='Основание лежит на оси Ox; высота — расстояние от C до этой оси.';}
  }
  if(topic===5){
   if(level===0){q=`Радиус окружности равен ${n}. Найди отношение длины окружности к π.`;a=2*n;s=[`Длина окружности C = 2πr.`,`C/π = 2·${n} = ${a}.`];h='Вспомни формулу длины окружности.';}
   if(level===1){q=`Радиус круга равен ${n}. Найди отношение его площади к π.`;a=n*n;s=[`Площадь круга S = πr².`,`S/π = ${n}² = ${a}.`];h='Квадрат радиуса умножается на π.';}
   if(level===2){q=`Радиусы двух концентрических окружностей равны ${n} и ${n+1}. Найди площадь кольца, делённую на π.`;a=2*n+1;s=[`Площадь кольца — разность площадей кругов.`,`S/π = ${n+1}² − ${n}² = ${a}.`];h='Вычти площадь меньшего круга из площади большего.';}
   if(level===3){q=`Площадь круга увеличили в ${n*n} раз. На сколько процентов увеличилась длина его окружности?`;a=(n-1)*100;s=[`Площадь пропорциональна квадрату радиуса, значит радиус увеличился в ${n} раз.`,`Длина окружности также увеличилась в ${n} раз, то есть на ${a}%.`];h='Свяжи изменение площади с изменением радиуса.';}
  }
  if(topic===6){
   if(level===0){q=`Размеры прямоугольного ящика ${n}, 3 и 4 см. Найди объём в см³.`;a=n*12;s=[`Объём равен произведению трёх измерений.`,`${n}·3·4 = ${a} см³.`];h='Умножь длину, ширину и высоту.';}
   if(level===1){q=`Ребро куба равно ${n} см. Найди площадь его полной поверхности в см².`;a=6*n*n;s=[`У куба 6 одинаковых квадратных граней.`,`S = 6·${n}² = ${a} см².`];h='Найди площадь одной грани и умножь на 6.';}
   if(level===2){q=`Объём прямоугольного сосуда ${n*60} см³, стороны его основания 5 и 6 см. Найди высоту в сантиметрах.`;a=n*2;s=[`Площадь основания равна 5·6 = 30 см².`,`Высота равна ${n*60} : 30 = ${a} см.`];h='Раздели объём на площадь основания.';}
   if(level===3){q=`Из куба с ребром ${n+1} см вырезали куб с ребром ${n} см. Найди объём оставшейся части в см³.`;a=(n+1)**3-n**3;s=[`Исходный объём равен ${n+1}³ = ${(n+1)**3} см³.`,`Вычитаем ${n}³ = ${n**3} см³ и получаем ${a} см³.`];h='Объём остатка равен разности объёмов.';}
  }
  add(topic,level,i,q,a,s,h);
 }
})();
